machine_patch.content:
// company/behaviors/dialog/machine.patch.js
// The COMPANY brand extension of the core dialog FSM (behavior-layer-design.md §3.2 / §5.2).
//
// PURELY ADDITIVE (monotonic). This patch is *merged* onto the core dialogMachine by the
// resolver's applyPatch() (§4.2) — it may ONLY add states / events / context keys. It must
// NOT delete, move, or rebind any core state (closed / open / animatingOut) or any existing
// core transition. The determinism gate (recipe action a7) asserts exactly that.
//
// This file never imports core/behaviors/dialog/machine.js and never mutates it on disk —
// core is read-only to the company bucket. The merge happens at fetch/compose time only.
//
// Patch grammar (consumed by applyPatch, §4.2):
//   context:     { ...newKeys }   — added to core context (additive; no core key removed)
//   addStates:   { <name>: node } — brand-new states only (name must NOT already exist in core)
//   amendStates: { <state>: { on: { <EVENT>: target } } }
//                                  — ADD new events to an existing core state's `on` map.
//                                    May only introduce NEW event keys; rebinding an existing
//                                    core event is a hard error in applyPatch (monotonic rule).

export const patch = {
  // New config key — brand chrome toggle (additive; core context keys untouched).
  context: { brandHeader: true },

  // Brand-new state: the dialog can be MINIMIZED. RESTORE returns to open; CLOSE still
  // funnels through the core animatingOut exit so focus/scroll cleanup stays canonical.
  addStates: {
    minimized: {
      on: { RESTORE: "open", CLOSE: "animatingOut" },
    },
  },

  // Amend the existing core `open` state by ADDING a MINIMIZE event (new event key only).
  // Core's `open` already owns CLOSE → animatingOut; that binding is left exactly as-is.
  amendStates: {
    open: {
      on: { MINIMIZE: "minimized" },
    },
  },
};

export default patch;

css.content:
/* company/design/dialog.css
 * The COMPANY brand design layer for the dialog (behavior-layer-design.md §3.2 / §5.2).
 *
 * Layered AFTER core/design/dialog.css (the resolver returns css = [ core, company ] in that
 * order — §4.2). It is purely ADDITIVE brand chrome: it styles the company-only `brandHeader`
 * part and the company-only `minimized` data-state, and applies brand accents to core parts via
 * the SAME contract selectors — it never edits the core CSS file.
 *
 * TOKEN-ONLY: every value is a real Style Dictionary token emitted into :root for both the
 * default and midnight themes (--color-semantic-primary-*/--space-*/--radius-*). No color is
 * hard-coded, so the brand chrome re-skins for free under any theme. Imports NO behavior/machine
 * file — design and behavior meet only at the parts.extend.md contract.
 */

/* ── Brand header: the company-only part, layered on top of [part="content"] ──── */
[part="brandHeader"] {
  /* The company demo puts the close button INSIDE this bar. Core now makes [part=content]
   * position:relative, so a bare absolute close would anchor to the content's top-right.
   * Making the brand header its OWN positioning context keeps the close anchored to the
   * HEADER bar (where the brand variant shows it) — additive, core file untouched. */
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  background: var(--color-semantic-primary-default);
  color: var(--color-semantic-primary-contrast);
  padding: var(--space-3) var(--space-6);
  /* sit flush with the rounded top of the core content surface */
  border-top-left-radius: var(--radius-lg);
  border-top-right-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  /* pull out to the content padding edges so the bar spans the surface */
  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-6)) var(--space-6);
}

[part="brandHeader"]:hover {
  background: var(--color-semantic-primary-hover);
}

/* ── Brand accent on the core close affordance (additive — core file untouched) ── */
[part="content"] [part="brandHeader"] [part="close"] {
  color: var(--color-semantic-primary-contrast);
}

/* ── Minimized: the company-only data-state (collapse to just the brand header) ── */
[part="content"][data-state="minimized"] {
  /* show only the brand header chrome; hide the body until RESTORE */
  overflow: hidden;
  max-height: none;
  padding-bottom: 0;
}

[part="content"][data-state="minimized"] > :not([part="brandHeader"]) {
  display: none;
}
